func (t *Trie) Insert(word string) {
	node := t.root
	for _, c := range word {
		i := c - 'a'
		if node.children[i] == nil {
			node.children[i] = &TrieNode{} // 没有路就新建
		}
		node = node.children[i]
	}
	node.isEnd = true // 标记单词结尾
